    func test_orderstats_layouts() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.median(x), MfArray([4.5] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.median(x) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.stats.median(x), MfArray([4.5] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 1e-05, "Matft.stats.median(x) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.median(x, axis: 0), MfArray([5.0, 3.0, 4.0, 6.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, "Matft.stats.median(x, axis: 0) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.stats.median(x, axis: 0), MfArray([5.0, 3.0, 4.0, 6.0] as [Double], mftype: .Float, shape: [4]), rtol: 1e-05, atol: 1e-05, "Matft.stats.median(x, axis: 0) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.median(x, axis: 1), MfArray([2.0, 5.5, 5.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.median(x, axis: 1) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.stats.median(x, axis: 1), MfArray([2.0, 5.5, 5.0] as [Double], mftype: .Float, shape: [3]), rtol: 1e-05, atol: 1e-05, "Matft.stats.median(x, axis: 1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.median(x, axis: -1), MfArray([2.0, 5.5, 5.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.median(x, axis: -1) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.stats.median(x, axis: -1), MfArray([2.0, 5.5, 5.0] as [Double], mftype: .Float, shape: [3]), rtol: 1e-05, atol: 1e-05, "Matft.stats.median(x, axis: -1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 0, method: .linear), MfArray([4.2, 1.4, 1.5999999999999996, 4.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 0, method: .linear) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 1, method: .linear), MfArray([0.7999999999999998, 4.299999999999999, 4.8] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 1, method: .linear) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 0, method: .lower), MfArray([3.0, -1.0, -2.0, 1.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 0, method: .lower) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 1, method: .lower), MfArray([-1.0, -2.0, 3.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 1, method: .lower) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 0, method: .higher), MfArray([5.0, 3.0, 4.0, 6.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 0, method: .higher) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 1, method: .higher), MfArray([1.0, 5.0, 5.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 1, method: .higher) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 0, method: .nearest), MfArray([5.0, 3.0, 4.0, 6.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 0, method: .nearest) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 1, method: .nearest), MfArray([1.0, 5.0, 5.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 1, method: .nearest) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 0, method: .midpoint), MfArray([4.0, 1.0, 1.0, 3.5] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 0, method: .midpoint) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: 30, axis: 1, method: .midpoint), MfArray([0.0, 1.5, 4.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: 30, axis: 1, method: .midpoint) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.quantile(x, q: [0.1, 0.9], axis: 1, keepDims: true), MfArray([-0.3999999999999999, 0.10000000000000053, 3.6, 3.7, 8.100000000000001, 7.1000000000000005] as [Double], mftype: .Double, shape: [2, 3, 1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.quantile(x, q: [0.1, 0.9], axis: 1, keepDims: true) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.percentile(x, q: [0, 100]), MfArray([-2.0, 9.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(x, q: [0, 100]) \(name)")
        }
        XCTAssertClose(Matft.stats.median(MfArray([7.5] as [Double])), MfArray([7.5] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.median(MfArray([7.5] as [Double]))")
        XCTAssertClose(Matft.stats.percentile(MfArray([[7.5]] as [[Double]]), q: 40, axis: 0), MfArray([7.5] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.percentile(MfArray([[7.5]] as [[Double]]), q: 40, axis: 0)")
    }

    func test_nan_functions_layouts() {
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.nansum(x), MfArray([27.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.nansum(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.nanmean(x), MfArray([3.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.nanmean(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.nanmax(x), MfArray([7.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.nanmax(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.nanmin(x), MfArray([1.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.nanmin(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.nanmedian(x), MfArray([2.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.nanmedian(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertEqual(Matft.stats.nanargmax(x), MfArray([9] as [Int], mftype: .Int, shape: [1]), "Matft.stats.nanargmax(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertEqual(Matft.stats.nanargmin(x), MfArray([0] as [Int], mftype: .Int, shape: [1]), "Matft.stats.nanargmin(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.nanvar(x, keepDims: true, ddof: 0), MfArray([3.5555555555555554] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, "Matft.stats.nanvar(x, keepDims: true, ddof: 0) \(name)")
