    func test_searching() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.where(x > 2, x, -x), MfArray([3.0, 1.0, 4.0, -1.0, 5.0, 9.0, 2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.where(x > 2, x, -x) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.where(x > 2, x, MfArray([0.5, -0.5, 1.5, -1.5] as [Double])), MfArray([3.0, -0.5, 4.0, -1.5, 5.0, 9.0, 1.5, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.where(x > 2, x, MfArray([0.5, -0.5, 1.5, -1.5] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.where(x > 2, 100.0, x), MfArray([100.0, -1.0, 100.0, 1.0, 100.0, 100.0, -2.0, 100.0, 100.0, 100.0, 100.0, 100.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.where(x > 2, 100.0, x) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.where(x > 2, x, 0.25), MfArray([3.0, 0.25, 4.0, 0.25, 5.0, 9.0, 0.25, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.where(x > 2, x, 0.25) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.where(x > 2, x, MfArray([.nan] as [Double])), MfArray([.nan, .nan, 3.0, 4.0, .nan, 5.0, .nan, .nan, .nan, 7.0, .nan, .nan] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.where(x > 2, x, MfArray([.nan] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(S){
            XCTAssertEqual(Matft.searchsorted(x, MfArray([-5, -1, 0.5, 5, 10] as [Double]), side: .left), MfArray([0, 1, 4, 5, 8] as [Int], mftype: .Int, shape: [5]), "Matft.searchsorted(x, MfArray([-5, -1, 0.5, 5, 10] as [Double]), side: .left) \(name)")
        }
        for (name, x) in layoutVariants(S){
            XCTAssertEqual(Matft.searchsorted(x, MfArray([-5, -1, 0.5, 5, 10] as [Double]), side: .right), MfArray([0, 3, 4, 7, 8] as [Int], mftype: .Int, shape: [5]), "Matft.searchsorted(x, MfArray([-5, -1, 0.5, 5, 10] as [Double]), side: .right) \(name)")
        }
        for (name, x) in layoutVariants(S){
            XCTAssertEqual(Matft.searchsorted(MfArray([-5, -1, 0.5, 5, 10] as [Double]), x), MfArray([1, 1, 1, 2, 3, 3, 3, 4] as [Int], mftype: .Int, shape: [8]), "Matft.searchsorted(MfArray([-5, -1, 0.5, 5, 10] as [Double]), x) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertEqual(Matft.digitize(x, bins: MfArray([-1, 2, 5] as [Double])), MfArray([2, 1, 2, 1, 3, 3, 0, 3, 3, 2, 3, 3] as [Int], mftype: .Int, shape: [3, 4]), "Matft.digitize(x, bins: MfArray([-1, 2, 5] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertEqual(Matft.digitize(x, bins: MfArray([-1, 2, 5] as [Double]), right: true), MfArray([2, 0, 2, 1, 2, 3, 0, 3, 2, 2, 2, 3] as [Int], mftype: .Int, shape: [3, 4]), "Matft.digitize(x, bins: MfArray([-1, 2, 5] as [Double]), right: true) \(name)")
        }
        do {
            for (name, x) in layoutVariants(A){
                let (hist, edges) = Matft.histogram(x, bins: 4)
                XCTAssertEqual(hist, MfArray([2, 3, 5, 2] as [Int], mftype: .Int, shape: [4]), name)
                XCTAssertClose(edges, MfArray([-2.0, 0.75, 3.5, 6.25, 9.0] as [Double], mftype: .Double, shape: [5]), rtol: 1e-12, atol: 1e-12, name)
            }
        }
        do {
            let (hist, edges) = Matft.histogram(MfArray([5.0, 5.0, 5.0] as [Double]), bins: 4)
            XCTAssertEqual(hist, MfArray([0, 0, 3, 0] as [Int], mftype: .Int, shape: [4]))
            XCTAssertClose(edges, MfArray([4.5, 4.75, 5.0, 5.25, 5.5] as [Double], mftype: .Double, shape: [5]), rtol: 1e-12)
        }
        do {
            let (hist, edges) = Matft.histogram(A, bins: 3, range: (0, 6))
            XCTAssertEqual(hist, MfArray([1, 2, 5] as [Int], mftype: .Int, shape: [3]))
            XCTAssertClose(edges, MfArray([0.0, 2.0, 4.0, 6.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-12)
        }
        XCTAssertEqual(Matft.bincount(MfArray([] as [Int], shape: [0])), MfArray([] as [Int], mftype: .Int, shape: [0]))
        XCTAssertEqual(Matft.bincount(MfArray([] as [Int], shape: [0]), minlength: 3), MfArray([0, 0, 0] as [Int], mftype: .Int, shape: [3]))
        XCTAssertEqual(Matft.bincount(MfArray([3, 1, 1, 0, 3, 3] as [Int])[Matft.reverse]), MfArray([1, 2, 0, 3] as [Int], mftype: .Int, shape: [4]))
    }

    func test_setops() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.unique(x), MfArray([-2.0, -1.0, 1.0, 3.0, 4.0, 5.0, 6.0, 8.0, 9.0] as [Double], mftype: .Double, shape: [9]), rtol: 1e-10, atol: 1e-10, "Matft.unique(x) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.unique(x), MfArray([-2.0, -1.0, 1.0, 3.0, 4.0, 5.0, 6.0, 8.0, 9.0] as [Double], mftype: .Float, shape: [9]), rtol: 1e-05, atol: 1e-05, "Matft.unique(x) \(name)")
        }
        for (name, x) in layoutVariants(AI){
            XCTAssertEqual(Matft.unique(x), MfArray([-2, -1, 1, 3, 4, 5, 6, 8, 9] as [Int], mftype: .Int, shape: [9]), "Matft.unique(x) \(name)")
        }
        for (name, x) in layoutVariants(B){
            XCTAssertEqual(Matft.unique(x), MfArray([false, true] as [Bool], shape: [2]), "Matft.unique(x) \(name)")
        }
        for (name, x) in layoutVariants(A){
            let (values, counts) = Matft.unique_counts(x)
            XCTAssertClose(values, MfArray([-2.0, -1.0, 1.0, 3.0, 4.0, 5.0, 6.0, 8.0, 9.0] as [Double], mftype: .Double, shape: [9]), rtol: 1e-12, name)
            XCTAssertEqual(counts, MfArray([1, 1, 1, 2, 1, 3, 1, 1, 1] as [Int], mftype: .Int, shape: [9]), name)
        }
        for (name, x) in layoutVariants(A){
            let (_, inverse) = Matft.unique_inverse(x)
            XCTAssertEqual(inverse, MfArray([3, 1, 4, 2, 5, 8, 0, 6, 5, 3, 5, 7] as [Int], mftype: .Int, shape: [3, 4]), name)
        }
        for (name, x) in layoutVariants(A){
            XCTAssertEqual(Matft.isin(x, MfArray([5, -1, 100] as [Double])), MfArray([false, true, false, false, true, false, false, false, true, false, true, false] as [Bool], shape: [3, 4]), "Matft.isin(x, MfArray([5, -1, 100] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertEqual(Matft.isin(x, MfArray([5, -1, 100] as [Double]), invert: true), MfArray([true, false, true, true, false, true, true, true, false, true, false, true] as [Bool], shape: [3, 4]), "Matft.isin(x, MfArray([5, -1, 100] as [Double]), invert: true) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.intersect1d(x, MfArray([9, 5, 0, 3] as [Double])), MfArray([3.0, 5.0, 9.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, "Matft.intersect1d(x, MfArray([9, 5, 0, 3] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.union1d(x, MfArray([10, 0] as [Double])), MfArray([-2.0, -1.0, 0.0, 1.0, 3.0, 4.0, 5.0, 6.0, 8.0, 9.0, 10.0] as [Double], mftype: .Double, shape: [11]), rtol: 1e-10, atol: 1e-10, "Matft.union1d(x, MfArray([10, 0] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.setdiff1d(x, MfArray([5, 3, 100] as [Double])), MfArray([-2.0, -1.0, 1.0, 4.0, 6.0, 8.0, 9.0] as [Double], mftype: .Double, shape: [7]), rtol: 1e-10, atol: 1e-10, "Matft.setdiff1d(x, MfArray([5, 3, 100] as [Double])) \(name)")
        }
        XCTAssertEqual(Matft.unique(MfArray([] as [Double], shape: [0])).shape, [0])
        XCTAssertEqual(Matft.isin(MfArray([] as [Double], shape: [0]), MfArray([1.0] as [Double])).shape, [0])
        XCTAssertEqual(Matft.intersect1d(MfArray([] as [Double], shape: [0]), MfArray([1.0] as [Double])).shape, [0])
        XCTAssertEqual(Matft.setdiff1d(MfArray([1.0] as [Double]), MfArray([1.0] as [Double])).shape, [0])
        XCTAssertClose(Matft.union1d(MfArray([] as [Double], shape: [0]), MfArray([2.0, 1.0] as [Double])), MfArray([1.0, 2.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, "Matft.union1d(MfArray([] as [Double], shape: [0]), MfArray([2.0, 1.0] as [Double]))")
    }

