    #if !os(WASI) // LAPACK / interp1d are not available on WASI
    func test_fit() throws {
        for (name, x) in layoutVariants(M){
            let ret = try Matft.linalg.lstsq(x, MfArray([2.0, 2.5, 5.1, 6.9] as [Double]))
            XCTAssertClose(ret.x, MfArray([-0.24745762711864608, 1.0288135593220338] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, name)
            XCTAssertClose(ret.residuals, MfArray([0.19525423728813474] as [Double], mftype: .Double, shape: [1]), rtol: 1e-8, atol: 1e-10, name)
            XCTAssertEqual(ret.rank, 2, name)
            XCTAssertClose(ret.s, MfArray([9.505101892824838, 0.8081076704361172] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, name)
        }
        do {
            let ret = try Matft.linalg.lstsq(M.astype(.Float), MfArray([2.0, 2.5, 5.1, 6.9] as [Float]))
            XCTAssertClose(ret.x, MfArray([-0.2474576234817505, 1.0288136005401611] as [Double], mftype: .Float, shape: [2]), rtol: 1e-4, atol: 1e-4)
        }
        do {
            let xs = MfArray([5.0, 4.0, 2.0, 1.0, 0.0] as [Double])[Matft.reverse]
            let ys = MfArray([26.1, 15.9, 4.2, 1.8, 1.0] as [Double])[Matft.reverse]
            let p = try Matft.polyfit(xs, ys, deg: 2)
            XCTAssertClose(p, MfArray([1.1564935064935071, -0.8493506493506512, 1.1987012987012995] as [Double], mftype: .Double, shape: [3]), rtol: 1e-9, atol: 1e-10)
            XCTAssertClose(try Matft.polyfit(xs.astype(.Float), ys.astype(.Float), deg: 2), MfArray([1.1564935445785522, -0.84935063123703, 1.19870126247406] as [Double], mftype: .Float, shape: [3]), rtol: 1e-4, atol: 1e-4)
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.polyval(MfArray([2.0, -1.0, 0.5] as [Double])[Matft.reverse], x), MfArray([3.5, 3.5, 6.0, 1.5, 9.5, 33.5, 6.0, 14.0, 9.5, 3.5, 9.5, 26.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.polyval(MfArray([2.0, -1.0, 0.5] as [Double])[Matft.reverse], x) \(name)")
        }
        for (name, x) in layoutVariants(AF){
