        }
        XCTAssertEqual(try Matft.linalg.matrix_rank(MfArray([0, 3, 0] as [Int])), 1)
        XCTAssertEqual(try Matft.linalg.matrix_rank(MfArray([0, 0] as [Float])), 0)
        XCTAssertEqual(try Matft.linalg.matrix_rank(MfArray([[1, 2], [2, 4]] as [[Int]]).T), 1)
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.stats.cov(x), MfArray([4.916666666666666, -9.166666666666666, 1.0833333333333333, -9.166666666666666, 21.666666666666664, -1.5, 1.0833333333333333, -1.5, 4.25] as [Double], mftype: .Double, shape: [3, 3]), rtol: 1e-09, atol: 1e-10, "Matft.stats.cov(x) \(name)")
        }
