    #if !os(WASI) // LAPACK / interp1d are not available on WASI
    func test_interpolation() {
        for (name, x) in layoutVariants(NEWX){
            XCTAssertClose(Matft.interp(x, xp: MfArray([0.0, 1.0, 2.5, 4.0] as [Double]), fp: MfArray([1.0, -1.0, 3.0, 2.0] as [Double])), MfArray([1.0, 1.0, 0.0, 1.6666666269302368, 3.0, 2.066666603088379, 2.0] as [Double], mftype: .Float, shape: [7]), rtol: 1e-05, atol: 1e-05, "Matft.interp(x, xp: MfArray([0.0, 1.0, 2.5, 4.0] as [Double]), fp: MfArray([1.0, -1.0, 3.0, 2.0] as [Double])) \(name)")
        }
        for (name, x) in layoutVariants(NEWX){
            XCTAssertClose(Matft.interp(x, xp: MfArray([0.0, 1.0, 2.5, 4.0] as [Double])[Matft.reverse][Matft.reverse], fp: MfArray([1.0, -1.0, 3.0, 2.0] as [Double]), left: -9, right: 9), MfArray([-9.0, 1.0, 0.0, 1.6666666269302368, 3.0, 2.066666603088379, 9.0] as [Double], mftype: .Float, shape: [7]), rtol: 1e-05, atol: 1e-05, "Matft.interp(x, xp: MfArray([0.0, 1.0, 2.5, 4.0] as [Double])[Matft.reverse][Matft.reverse], fp: MfArray([1.0, -1.0, 3.0, 2.0] as [Double]), left: -9, right: 9) \(name)")
        }
        XCTAssertClose(Matft.interp1d.linear(x: MfArray([2.5, 0.0, 4.0, 1.0] as [Double]), y: MfArray([3.0, 1.0, 2.0, -1.0] as [Double]), assume_sorted: false).interpolate(MfArray([0.0, 0.5, 1.2, 2.5, 3.9, 4.0] as [Double])), MfArray([1.0, 0.0, -0.46666666865348816, 3.0, 2.066666603088379, 2.0] as [Double], mftype: .Float, shape: [6]), rtol: 1e-05, atol: 1e-05, "Matft.interp1d.linear(x: MfArray([2.5, 0.0, 4.0, 1.0] as [Double]), y: MfArray([3.0, 1.0, 2.0, -1.0] as [Double]), assume_sorted: false).interpolate(MfArray([0.0, 0.5, 1.2, 2.5, 3.9, 4.0] as [Double]))")
