    func test_math() {
        for (name, x) in layoutVariants(AN){
            XCTAssertEqual(Matft.math.isnan(x), MfArray([false, true, false, false, false, false, true, false, true, false, false, false] as [Bool], shape: [3, 4]), "Matft.math.isnan(x) \(name)")
        }
        for (name, x) in layoutVariants(Z){
            XCTAssertEqual(Matft.math.isnan(x), MfArray([false, false, false, false, true, false] as [Bool], shape: [2, 3]), "Matft.math.isnan(x) \(name)")
        }
        for (name, x) in layoutVariants(Z){
            XCTAssertEqual(Matft.math.isinf(x), MfArray([false, true, false, true, false, false] as [Bool], shape: [2, 3]), "Matft.math.isinf(x) \(name)")
        }
        for (name, x) in layoutVariants(Z){
            XCTAssertEqual(Matft.math.isfinite(x), MfArray([true, false, true, false, false, true] as [Bool], shape: [2, 3]), "Matft.math.isfinite(x) \(name)")
        }
        for (name, x) in layoutVariants(AI){
            XCTAssertEqual(Matft.math.isnan(x), MfArray([false, false, false, false, false, false, false, false, false, false, false, false] as [Bool], shape: [3, 4]), "Matft.math.isnan(x) \(name)")
        }
        for (name, x) in layoutVariants(AI){
            XCTAssertEqual(Matft.math.isfinite(x), MfArray([true, true, true, true, true, true, true, true, true, true, true, true] as [Bool], shape: [3, 4]), "Matft.math.isfinite(x) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 3), MfArray([27.0, -1.0, 64.0, 1.0, 125.0, 729.0, -8.0, 216.0, 125.0, 27.0, 125.0, 512.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, "Matft.math.power(bases: x, exponents: 3) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.math.power(bases: Matft.math.abs(x), exponents: 0.5), MfArray([1.7320507764816284, 1.0, 2.0, 1.0, 2.2360680103302, 3.0, 1.4142135381698608, 2.4494898319244385, 2.2360680103302, 1.7320507764816284, 2.2360680103302, 2.8284270763397217] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, "Matft.math.power(bases: Matft.math.abs(x), exponents: 0.5) \(name)")
        }
        for (name, x) in layoutVariants(AI){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 2), MfArray([9.0, 1.0, 16.0, 1.0, 25.0, 81.0, 4.0, 36.0, 25.0, 9.0, 25.0, 64.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, "Matft.math.power(bases: x, exponents: 2) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.math.exp2(x / 4), MfArray([1.681792830507429, 0.8408964152537145, 2.0, 1.189207115002721, 2.378414230005442, 4.756828460010884, 0.7071067811865476, 2.8284271247461903, 2.378414230005442, 1.681792830507429, 2.378414230005442, 4.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-12, atol: 1e-12, "Matft.math.exp2(x / 4) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.math.exp2(x / 4), MfArray([1.6817928552627563, 0.8408964276313782, 2.0, 1.1892070770263672, 2.3784141540527344, 4.756828308105469, 0.7071067690849304, 2.8284270763397217, 2.3784141540527344, 1.6817928552627563, 2.3784141540527344, 4.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-06, atol: 1e-06, "Matft.math.exp2(x / 4) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.math.expm1(x / 4), MfArray([1.1170000166126746, -0.22119921692859512, 1.7182818284590453, 0.2840254166877415, 2.4903429574618414, 8.487735836358526, -0.3934693402873666, 3.481689070338065, 2.4903429574618414, 1.1170000166126746, 2.4903429574618414, 6.38905609893065] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-12, atol: 1e-12, "Matft.math.expm1(x / 4) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.math.expm1(x / 4), MfArray([1.1169999837875366, -0.22119921445846558, 1.718281865119934, 0.2840254306793213, 2.490342855453491, 8.487735748291016, -0.39346933364868164, 3.481688976287842, 2.490342855453491, 1.1169999837875366, 2.490342855453491, 6.389056205749512] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-06, atol: 1e-06, "Matft.math.expm1(x / 4) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.math.log1p(Matft.math.abs(x) / 4), MfArray([0.5596157879354227, 0.22314355131420976, 0.6931471805599453, 0.22314355131420976, 0.8109302162163288, 1.1786549963416462, 0.4054651081081644, 0.9162907318741551, 0.8109302162163288, 0.5596157879354227, 0.8109302162163288, 1.0986122886681098] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-12, atol: 1e-12, "Matft.math.log1p(Matft.math.abs(x) / 4) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.math.log1p(Matft.math.abs(x) / 4), MfArray([0.5596157908439636, 0.2231435477733612, 0.6931471824645996, 0.2231435477733612, 0.8109301924705505, 1.1786550283432007, 0.40546509623527527, 0.9162907600402832, 0.8109301924705505, 0.5596157908439636, 0.8109301924705505, 1.0986123085021973] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-06, atol: 1e-06, "Matft.math.log1p(Matft.math.abs(x) / 4) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.math.square(x / 4), MfArray([0.5625, 0.0625, 1.0, 0.0625, 1.5625, 5.0625, 0.25, 2.25, 1.5625, 0.5625, 1.5625, 4.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-12, atol: 1e-12, "Matft.math.square(x / 4) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            XCTAssertClose(Matft.math.square(x / 4), MfArray([0.5625, 0.0625, 1.0, 0.0625, 1.5625, 5.0625, 0.25, 2.25, 1.5625, 0.5625, 1.5625, 4.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-06, atol: 1e-06, "Matft.math.square(x / 4) \(name)")
        }
        for (name, x) in layoutVariants(B){
            XCTAssertEqual(Matft.logical_not(x), MfArray([false, true, false, true, true, false] as [Bool], shape: [2, 3]), "Matft.logical_not(x) \(name)")
        }
    }
